//! Compares the crate against cached output of the C implementation
//! (`tests/oracle/*.txt`, regenerated by `tests/oracle/gen.php`; see the
//! ignored `regenerate_oracle` test).
//!
//! The oracle binary is PHP 8.3; php-src master differs in a few places
//! (getimagesize's `width_unit`/`height_unit` keys, HEIF/WebP support in
//! exif, ...).  Those cases are listed in `KNOWN_MASTER_DIFFERENCES` and
//! checked separately against the master `.phpt` expectations.

use std::fs::File;
use std::path::{Path, PathBuf};

use php_exif::diag::{Diagnostic, Level};
use php_exif::encoding::BuiltinConverter;
use php_exif::exif::{exif_read_data, exif_thumbnail, ExifConfig, ReadOptions, StreamOrigin};
use php_exif::imagesize::{getimagesize, getimagesizefromstring};
use php_exif::imagetype::exif_imagetype;
use php_runtime::serialize::serialize;
use php_runtime::{ArrayKey, CollectingContext, Value};

struct Case {
    id: String,
    diags: Vec<String>,
    result: Vec<u8>,
}

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests")
}

fn load(name: &str) -> Vec<Case> {
    let data = std::fs::read(root().join("oracle").join(name)).expect("oracle file");
    let mut cases = Vec::new();
    let mut pos = 0;
    let mut cur: Option<Case> = None;
    while pos < data.len() {
        let eol = data[pos..]
            .iter()
            .position(|&b| b == b'\n')
            .map_or(data.len(), |p| pos + p);
        let line = String::from_utf8_lossy(&data[pos..eol]).into_owned();
        pos = eol + 1;
        if let Some(id) = line.strip_prefix("#CASE ") {
            cur = Some(Case {
                id: id.to_owned(),
                diags: Vec::new(),
                result: Vec::new(),
            });
        } else if let Some(d) = line.strip_prefix("#DIAG ") {
            let (lvl, hex) = d.split_once(' ').unwrap_or((d, ""));
            let bytes: Vec<u8> = (0..hex.len() / 2)
                .map(|i| u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).unwrap_or(0))
                .collect();
            let c = cur.as_mut().expect("case");
            c.diags
                .push(format!("{lvl} {}", String::from_utf8_lossy(&bytes)));
        } else if let Some(n) = line.strip_prefix("#RESULT ") {
            let n: usize = n.parse().expect("length");
            let mut c = cur.take().expect("case");
            c.result = data[pos..pos + n].to_vec();
            pos += n + 1;
            cases.push(c);
        }
    }
    cases
}

fn fmt_diags(d: &[Diagnostic]) -> Vec<String> {
    d.iter()
        .map(|d| {
            let l = match d.level {
                Level::Warning => "W",
                Level::Notice => "N",
            };
            format!("{l} {}", d.message_lossy())
        })
        .collect()
}

fn ser(v: &Value) -> Vec<u8> {
    serialize(v, &mut CollectingContext::new()).expect("serialize")
}

fn origin(path: &Path) -> StreamOrigin {
    let meta = std::fs::metadata(path).expect("metadata");
    StreamOrigin::File {
        path: path.to_string_lossy().as_bytes().to_vec(),
        mtime: 0,
        size: meta.len(),
        regular: true,
    }
}

/// Cases where PHP 8.3 (the oracle) and php-src master legitimately differ.
/// Each entry was checked against the php-src master source / `.phpt`.
const KNOWN_MASTER_DIFFERENCES: &[&str] = &[
    // master prints the pointer-offset sum with %zX (no 32-bit truncation).
    "exif/bug60150.jpg",
    // master rejects TIFF entries whose length exceeds INT32_MAX
    // ("Read from TIFF: entry length of %ld exceeds INT32_MAX").
    "exif/bug71534.tiff",
    "exif/bug76130_2.jpg",
    "exif/bug77950.tiff",
    // master accepts an IFD without the trailing next-IFD offset instead of
    // warning "Illegal IFD size" (bug72094.phpt / gh11020.phpt).
    "exif/bug72094_3.jpg",
    "exif/bug77831.tiff",
    "exif/gh11020.jpg",
    // master knows the OffsetTime* tags (exif028.phpt).
    "exif/image028.jpg",
    // master reads Exif from HEIF (exif029.phpt, oss_fuzz_*.phpt) and
    // identifies HEIF in getimagesize()/exif_imagetype() (getimagesize.phpt).
    "exif/image029.heic",
    "image/test4pix.heic",
    "exif/oss_fuzz_442954659/input",
    "exif/oss_fuzz_444479893/input",
    "image/gh20201.avif",
    // master reads Exif from WebP (gh19904.phpt).
    "exif/gh19904.webp",
    "image/test12pix.webp",
    "image/test3llpix.webp",
    "image/test3pix.webp",
];

fn report(name: &str, mismatches: &[String]) {
    let unexpected: Vec<&String> = mismatches
        .iter()
        .filter(|m| {
            !KNOWN_MASTER_DIFFERENCES
                .iter()
                .any(|k| m.starts_with(&format!("{k}|")) || m.starts_with(&format!("{k}\n")))
        })
        .collect();
    for m in &unexpected {
        eprintln!("--- {name} mismatch: {m}");
    }
    assert!(
        unexpected.is_empty(),
        "{} {name} mismatches",
        unexpected.len()
    );
}

fn split_id(id: &str) -> Vec<&str> {
    id.split('|').collect()
}

#[test]
fn exif_read_data_matches_oracle() {
    let cfg = ExifConfig::default();
    let mut mismatches = Vec::new();
    for c in load("exif_read_data.txt") {
        let parts = split_id(&c.id);
        let path = root().join("fixtures").join(parts[0]);
        let sections = match parts[1] {
            "NULL" => None,
            s => Some(s.trim_matches('\'').as_bytes().to_vec()),
        };
        let opts = ReadOptions {
            required_sections: sections,
            as_arrays: parts[2] == "1",
            read_thumbnail: parts[3] == "1",
        };
        let f = File::open(&path).expect("open");
        let (v, d) = exif_read_data(f, &origin(&path), &opts, &cfg, &BuiltinConverter);
        let got = ser(&v);
        let gd = fmt_diags(&d);
        if got != c.result || gd != c.diags {
            mismatches.push(format!(
                "{}\n  want diags {:?}\n  got  diags {:?}\n  want {}\n  got  {}",
                c.id,
                c.diags,
                gd,
                String::from_utf8_lossy(&c.result)
                    .chars()
                    .take(3000)
                    .collect::<String>(),
                String::from_utf8_lossy(&got)
                    .chars()
                    .take(3000)
                    .collect::<String>()
            ));
        }
    }
    report("exif_read_data", &mismatches);
}

#[test]
#[allow(clippy::many_single_char_names)]
fn exif_thumbnail_matches_oracle() {
    let cfg = ExifConfig::default();
    let mut mismatches = Vec::new();
    for c in load("exif_thumbnail.txt") {
        let parts = split_id(&c.id);
        let path = root().join("fixtures").join(parts[0]);
        let want_dims = parts[1] == "whT";
        let f = File::open(&path).expect("open");
        let (r, d) = exif_thumbnail(f, &origin(&path), want_dims, &cfg, &BuiltinConverter);
        let data = r
            .as_ref()
            .map_or(Value::Bool(false), |t| Value::string(t.data.as_slice()));
        let v = if want_dims {
            let (w, h, t) = r
                .as_ref()
                .map_or((Value::Null, Value::Null, Value::Null), |t| {
                    (
                        Value::Int(t.width),
                        Value::Int(t.height),
                        Value::Int(t.image_type),
                    )
                });
            Value::Array([data, w, h, t].into_iter().collect())
        } else {
            data
        };
        let got = ser(&v);
        let gd = fmt_diags(&d);
        if got != c.result || gd != c.diags {
            mismatches.push(format!(
                "{}\n  want diags {:?}\n  got  diags {:?}\n  want {}\n  got  {}",
                c.id,
                c.diags,
                gd,
                String::from_utf8_lossy(&c.result)
                    .chars()
                    .take(300)
                    .collect::<String>(),
                String::from_utf8_lossy(&got)
                    .chars()
                    .take(300)
                    .collect::<String>()
            ));
        }
    }
    report("exif_thumbnail", &mismatches);
}

fn strip_units(v: Value) -> Value {
    match v {
        Value::Array(mut a) => {
            let t = a.make_mut();
            t.remove(&ArrayKey::from_bytes(b"width_unit"));
            t.remove(&ArrayKey::from_bytes(b"height_unit"));
            Value::Array(a)
        }
        v => v,
    }
}

#[test]
fn imagetype_and_getimagesize_match_oracle() {
    let mut mismatches = Vec::new();
    for c in load("imagetype.txt") {
        let parts = split_id(&c.id);
        let path = root().join("fixtures").join(parts[0]);
        let input = path.to_string_lossy().as_bytes().to_vec();
        let (v, d) = match parts[1] {
            "exif_imagetype" => {
                let (t, d) = exif_imagetype(File::open(&path).expect("open"), &input);
                (t.map_or(Value::Bool(false), Value::Int), d)
            }
            "getimagesize" => {
                let o = getimagesize(File::open(&path).expect("open"), &input, true);
                let info = Value::Array(o.app_markers.clone().unwrap_or_default().into());
                let v = strip_units(o.to_value());
                (Value::Array([v, info].into_iter().collect()), o.diagnostics)
            }
            _ => {
                let data = std::fs::read(&path).expect("read");
                let o = getimagesizefromstring(&data, false);
                (strip_units(o.to_value()), o.diagnostics)
            }
        };
        let got = ser(&v);
        let gd = fmt_diags(&d);
        let want_diags: Vec<String> = c
            .diags
            .iter()
            .map(|s| {
                s.replace(
                    &root().join("fixtures").to_string_lossy().to_string(),
                    &root().join("fixtures").to_string_lossy(),
                )
            })
            .collect();
        if got != c.result || gd != want_diags {
            mismatches.push(format!(
                "{}|\n  want diags {:?}\n  got  diags {:?}\n  want {}\n  got  {}",
                c.id,
                want_diags,
                gd,
                String::from_utf8_lossy(&c.result)
                    .chars()
                    .take(300)
                    .collect::<String>(),
                String::from_utf8_lossy(&got)
                    .chars()
                    .take(300)
                    .collect::<String>()
            ));
        }
    }
    report("imagetype", &mismatches);
}

#[test]
fn tagnames_match_oracle() {
    let text = std::fs::read_to_string(root().join("oracle/tagname.txt")).expect("tagname.txt");
    let mut want = std::collections::BTreeMap::new();
    for line in text.lines() {
        let (n, name) = line.split_once(' ').expect("line");
        want.insert(n.parse::<i64>().expect("int"), name.to_owned());
    }
    // master: 0x8824 renamed, OffsetTime* (0x9010-0x9012) added.
    want.insert(0x8824, "SpectralSensitivity".to_owned());
    want.insert(0x9010, "OffsetTime".to_owned());
    want.insert(0x9011, "OffsetTimeOriginal".to_owned());
    want.insert(0x9012, "OffsetTimeDigitized".to_owned());
    for i in -2..=0x10001_i64 {
        assert_eq!(
            php_exif::exif::exif_tagname(i).map(str::to_owned),
            want.get(&i).cloned(),
            "tag {i}"
        );
    }
}

#[test]
#[ignore = "regenerates the oracle files with /usr/bin/php"]
fn regenerate_oracle() {
    let status = std::process::Command::new("/usr/bin/php")
        .args(["-d", "memory_limit=1G"])
        .arg(root().join("oracle/gen.php"))
        .status()
        .expect("run php");
    assert!(status.success());
}

#[test]
fn iptc_matches_oracle() {
    let iptc = b"\x1C\x02x\x00\x0ATest image\x1C\x02t\x00\x05(c)PH";
    let mut mismatches = Vec::new();
    let mut last_embed: Option<Vec<u8>> = None;
    for c in load("iptc.txt") {
        let parts = split_id(&c.id);
        let path = root().join("fixtures").join(parts[0]);
        let data = std::fs::read(&path).expect("read");
        let v = if parts[1] == "iptcembed" {
            let r = php_exif::iptc::iptcembed(iptc, &data, 0);
            last_embed = r.result.clone().ok().flatten();
            match r.result {
                Ok(Some(b)) => Value::string(b.as_slice()),
                Ok(None) => Value::Bool(true),
                Err(()) => Value::Bool(false),
            }
        } else {
            php_exif::iptc::iptcparse(last_embed.as_deref().unwrap_or(&data))
        };
        if ser(&v) != c.result {
            mismatches.push(format!("{}|", c.id));
        }
    }
    report("iptc", &mismatches);
}
